import pyomo.environ as pyo

DATA = {
    "vehicle_types": ["large", "small"],
    "capacity": {"large": 6, "small": 2},
    "spots": {"large": 2, "small": 1},
    "min_people": 80,
    "min_small_units": 5,
    "large_fraction": 0.75,
}

def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.V = pyo.Set(initialize=d["vehicle_types"])

    def cap_rule(m, v):
        return (0, None)
    model.units = pyo.Var(model.V, domain=pyo.NonNegativeIntegers)

    def obj_rule(m):
        return sum(d["spots"][v] * m.units[v] for v in m.V)
    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def people_rule(m):
        return sum(d["capacity"][v] * m.units[v] for v in m.V) >= d["min_people"]
    model.people = pyo.Constraint(rule=people_rule)

    def small_rule(m):
        return m.units["small"] >= d["min_small_units"]
    model.small_min = pyo.Constraint(rule=small_rule)

    def large_share_rule(m):
        frac = d["large_fraction"]
        return (frac - 1.0) * m.units["large"] + frac * m.units["small"] <= 0
    model.large_share = pyo.Constraint(rule=large_share_rule)

    return model

